function ActivityCustomTrainNode:OnClickBtnGroupHandler()
    ---@type CustomTrainComponent 
    local CustomTrainComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CustomTrainComponent)
    local serverTime = GameUtils.GetServerTime()
    if isNull(self.customTrainDojo) then
