--region public
---@param activityDojo ActivityDojo
function ActivityCustomTrainNode:Refresh(activityDojo)
    self._activityDojo = activityDojo

    if isNull(self._activityDojo) then
        return
    end
    if isNull(self.customTrainDojo) then
        GameUtils.Request(Interfaces.CustomizedTrainingHome , {} , function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
            local data = response.data 
            ---@type CustomTrainComponent 
            local CustomTrainComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CustomTrainComponent)
            CustomTrainComponent:FillData(data)
            self.customTrainDojo = CustomTrainComponent:GetDojo()
            local serverTime = GameUtils.GetServerTime()
            local unlock = false
            if self.customTrainDojo:GetIsOpened() > 0 then
                if GameUtils.IsUnlocked(Constants.SystemToggleIds.Id120036)  then
                    unlock = true
                end
            end
            
            CfUtils.SetActive(self.Unlock , unlock) 
            CfUtils.SetActive(self.Lock , not unlock) 
            self:RefreshUI()
            local isOpened = self.customTrainDojo:GetIsOpened()
            local statusLeftSeconds = self.customTrainDojo:GetStatusLeftSeconds()
            if statusLeftSeconds - 86400 > GameUtils.GetServerTime() then
            else 
                if isNotNull(self.statusLeftTimer) then
                    CDTimerModule.GetInstance():RemoveCD(self.statusLeftTimer)
                    self.statusLeftTimer = nil
                end
                self.statusLeftTimer = CDTimerModule:GetInstance():AddCD(1, function(count, id)
                    
                    if statusLeftSeconds <= 0 then
                        -- 结束
                        CDTimerModule.GetInstance():RemoveCD(self.statusLeftTimer)
                        KTool.SetActive(self.RestTxtTime.gameObject, false)
                        self:Refresh(self._activityDojo)
                    else
                        if isOpened then
                            self:RefreshEndTime()
                        else 
                            self:StartTimeText()
                        end
                    end
                end,  statusLeftSeconds + 10000, false, true, true)
            end
        end)
    end
end
--endregion public

--region private
function ActivityCustomTrainNode:RefreshUI(unlock)
    self:RefreshActivityTime()
    self:RefreshStateGroup()
    if self.customTrainDojo:GetIsOpened() then
        self:RefreshEndTime()
    else
        self:StartTimeText()
    end
    self:RefreshTitleImg()
end

function ActivityCustomTrainNode:RefreshTitleImg()
    local titleImgUrl = checkString(self._activityDojo.titleImage)
    if not string.isEmpty(titleImgUrl) then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end
    ---@type ActivityMgr
    local ActivityMgr = import('Game.Activity.ActivityMgr')
    CfUtils.FillText(self.TxtDesc , ActivityMgr.GetActivityRule("12003601"))
end

function ActivityCustomTrainNode:RefreshActivityTime()
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self.customTrainDojo:GetStartTime(), self.customTrainDojo:GetEndTime()))
end

function ActivityCustomTrainNode:RefreshStateGroup()
    -- CfUtils.FillText(self.Text, self._activityDojo.detail)
end
function ActivityCustomTrainNode:StartTimeText()
    CfUtils.FillText(self.TextLockDesc, localize("距离活动开始时间:_time_",{_time_ = ActivityUtils.ConventLeftTimeText(self.customTrainDojo:GetStatusLeftSeconds())}) )
end

function ActivityCustomTrainNode:RefreshEndTime()
    CfUtils.FillText(self.TextTime2, ActivityUtils.ConventLeftTimeText(self.customTrainDojo:GetStatusLeftSeconds()))
end

return ActivityCustomTrainNode